import{p as e,l as c,v as u,h as a,a as b,s as v}from"./Spqg9yC3.js";const M=(t,i)=>t[i],E=t=>t.sections.filter(i=>!i.when||i.when());function y(t){const i=[],g=/\*\*(.+?)\*\*|\[([^\]]+)\]\(([^)\s]+)\)/g;let l=0;for(const r of t.matchAll(g)){const p=r.index??0;p>l&&i.push({kind:"text",value:t.slice(l,p)}),r[1]!==void 0?i.push({kind:"strong",value:r[1]}):i.push({kind:"link",value:r[2],href:r[3]}),l=p+r[0].length}return l<t.length&&i.push({kind:"text",value:t.slice(l)}),i}const x=t=>y(t).map(i=>i.value).join(""),m=`[${e.email}](mailto:${e.email})`,n=t=>({fr:t,en:t}),S={id:"cookies",path:"/cookies",title:{fr:"Politique cookies",en:"Cookie policy"},short:{fr:"Cookies",en:"Cookies"},updated:c.cookies,essentials:[{fr:"Le site n’utilise que des cookies nécessaires à son fonctionnement : langue, paiement, connexion. Ils ne demandent pas d’accord.",en:"The website only uses the cookies it needs to work: language, payment, sign-in. They do not require consent."},{fr:"Aucun cookie publicitaire, aucun outil de mesure tiers.",en:"No advertising cookies, no third-party measurement tool."},{fr:"La fréquentation du site est mesurée sans cookie. Vous pouvez vous y opposer ci-dessous.",en:"Traffic to the website is measured without cookies. You can object to it below."}],sections:[{id:"choice",title:{fr:"Vos choix",en:"Your choices"},blocks:[{kind:"choice"}]},{id:"what",title:{fr:"Qu’est-ce qu’un traceur ?",en:"What is a tracker?"},blocks:[{kind:"p",text:{fr:"Un cookie est un petit fichier enregistré par votre navigateur lorsque vous consultez un site. Le stockage local du navigateur joue un rôle comparable. Ces traceurs permettent de mémoriser une information d’une page à l’autre ou d’une visite à l’autre.",en:"A cookie is a small file stored by your browser when you visit a website. The browser’s local storage plays a similar role. These trackers remember a piece of information from one page or visit to the next."}}]},{id:"necessary",title:{fr:"Traceurs nécessaires",en:"Necessary trackers"},blocks:[{kind:"p",text:{fr:"Ils sont indispensables au service que vous demandez et sont exemptés de consentement. Les cookies de IMPERIUM ne sont pas lisibles par les scripts de la page.",en:"They are essential to the service you ask for and are exempt from consent. IMPERIUM’s cookies cannot be read by the page’s scripts."}},{kind:"table",head:[{fr:"Nom",en:"Name"},{fr:"Rôle",en:"Purpose"},{fr:"Émetteur",en:"Set by"},{fr:"Durée",en:"Duration"}],rows:[[n("sybiosme_locale"),{fr:"Mémoriser la langue et la devise choisies",en:"Remembering the chosen language and currency"},n("IMPERIUM"),{fr:"1 an",en:"1 year"}],[n("sybiosme_checkout"),{fr:"Reprendre la commande en cours",en:"Resuming the order in progress"},n("IMPERIUM"),{fr:"24 heures",en:"24 hours"}],[n("sb-…-auth-token"),{fr:"Maintenir la session de l’espace client",en:"Keeping the client space session"},{fr:"IMPERIUM (Supabase)",en:"IMPERIUM (Supabase)"},{fr:"30 jours",en:"30 days"}],[n("sybiosme_login, sybiosme_claim"),{fr:"Vérifier le code de connexion reçu par email",en:"Checking the sign-in code received by email"},n("IMPERIUM"),{fr:"10 minutes",en:"10 minutes"}],[n("sybiosme_oauth, sybiosme_auth_next"),{fr:"Sécuriser la connexion avec Google ou Microsoft",en:"Securing sign-in with Google or Microsoft"},n("IMPERIUM"),{fr:"10 minutes",en:"10 minutes"}],[n("__stripe_mid, __stripe_sid"),{fr:"Sécuriser le paiement et prévenir la fraude",en:"Securing payment and preventing fraud"},n("Stripe"),{fr:"1 an ; 30 minutes",en:"1 year; 30 minutes"}],[{fr:"Stockage local",en:"Local storage"},{fr:"Garder le brouillon du questionnaire et l’état de l’onglet",en:"Keeping the questionnaire draft and the tab’s state"},n("IMPERIUM"),{fr:"Jusqu’à l’envoi du questionnaire ou la fermeture de l’onglet",en:"Until the questionnaire is sent or the tab is closed"}],[{fr:"Stockage local (sybiosme_measure)",en:"Local storage (sybiosme_measure)"},{fr:"Mémoriser votre opposition à la mesure d’audience, si vous l’exprimez",en:"Remembering your objection to audience measurement, if you make one"},n("IMPERIUM"),{fr:"Jusqu’à ce que vous changiez d’avis",en:"Until you change your mind"}]]}]},{id:"audience",title:{fr:"Mesure d’audience sans cookie",en:"Audience measurement without cookies"},blocks:[{kind:"p",text:{fr:"IMPERIUM mesure la fréquentation de son site avec son propre outil, sans cookie et sans service tiers : rien n’est enregistré sur votre appareil pour cette mesure, et votre adresse IP n’est jamais conservée. Elle ne fonctionne pas dans l’espace client. Ce qui est mesuré, combien de temps et sur quelle base est détaillé dans la [politique de confidentialité](/privacy#audience).",en:"IMPERIUM measures traffic to its website with its own tool, without cookies and without any third-party service: nothing is stored on your device for this measurement, and your IP address is never kept. It does not run in the client space. What is measured, for how long and on what basis is set out in the [privacy policy](/privacy#audience)."}},{kind:"p",text:{fr:"Vous pouvez vous y opposer depuis cette page ou depuis la politique de confidentialité. Si votre navigateur envoie le signal Global Privacy Control, rien n’est mesuré.",en:"You can object to it from this page or from the privacy policy. If your browser sends the Global Privacy Control signal, nothing is measured."}}]},{id:"browser",title:{fr:"Les réglages de votre navigateur",en:"Your browser settings"},blocks:[{kind:"p",text:{fr:"Vous pouvez aussi bloquer ou supprimer les cookies depuis les réglages de votre navigateur. Bloquer les cookies nécessaires peut empêcher le paiement ou la connexion à l’espace client.",en:"You can also block or delete cookies in your browser settings. Blocking necessary cookies may prevent payment or signing in to the client space."}},{kind:"p",text:{fr:"Le paiement par PayPal ou par portefeuille (Apple Pay, Google Pay, Link) s’ouvre dans une fenêtre du prestataire, qui applique sa propre politique.",en:"Paying with PayPal or a wallet (Apple Pay, Google Pay, Link) opens a window run by that provider, under its own policy."}}]},{id:"contact",title:{fr:"Contact",en:"Contact"},blocks:[{kind:"p",text:{fr:`Pour toute question sur les cookies ou la mesure d’audience : ${m}.`,en:`For any question about cookies or audience measurement: ${m}.`}}]}]},d=`[${e.email}](mailto:${e.email})`,w={id:"notice",path:"/legal-notice",title:{fr:"Mentions légales",en:"Legal notice"},short:{fr:"Mentions légales",en:"Legal notice"},updated:c.notice,sections:[{id:"publisher",title:{fr:"Éditeur du site",en:"Publisher"},blocks:[{kind:"p",text:{fr:`Ce site est édité par ${e.person}, entrepreneur individuel, qui exerce sous le nom commercial ${e.brand}.`,en:`This website is published by ${e.person}, a sole trader (French “entrepreneur individuel”) trading as ${e.brand}.`}},{kind:"facts",items:[{label:{fr:"Dénomination",en:"Legal name"},value:{fr:e.denomination,en:e.denomination}},{label:{fr:"Nom commercial",en:"Trading name"},value:{fr:e.brand,en:e.brand}},{label:{fr:"Adresse",en:"Address"},value:{fr:`${e.street}, ${e.postalCode} ${e.city}, France`,en:`${e.street}, ${e.postalCode} ${e.city}, France`}},{label:{fr:"SIREN",en:"SIREN"},value:{fr:`${e.siren}, immatriculé au Registre national des entreprises (RNE)`,en:`${e.siren}, registered with the French National Business Register (RNE)`}},{label:{fr:"SIRET",en:"SIRET"},value:{fr:e.siret,en:e.siret}},{label:{fr:"Code APE",en:"Activity code"},value:{fr:`${e.naf}, programmation informatique`,en:`${e.naf}, computer programming`}},{label:{fr:"TVA",en:"VAT"},value:{fr:u.fr,en:u.en}},{label:{fr:"Téléphone",en:"Telephone"},value:{fr:`[${e.phone}](${e.phoneHref})`,en:`[${e.phone}](${e.phoneHref})`}},{label:{fr:"Email",en:"Email"},value:{fr:d,en:d}}]}]},{id:"director",title:{fr:"Directeur de la publication",en:"Publication director"},blocks:[{kind:"p",text:{fr:`${e.person}.`,en:`${e.person}.`}}]},{id:"host",title:{fr:"Hébergement",en:"Hosting"},blocks:[{kind:"p",text:{fr:`Le site est hébergé par ${a.name}, ${a.address}, États-Unis. Contact : [vercel.com/contact](${a.contact}).`,en:`The website is hosted by ${a.name}, ${a.address}, United States. Contact: [vercel.com/contact](${a.contact}).`}},{kind:"p",text:{fr:"Les données de l’espace client sont stockées par Supabase, Inc. dans un centre de données situé à Paris.",en:"Client space data is stored by Supabase, Inc. in a data centre located in Paris."}}]},{id:"ip",title:{fr:"Propriété intellectuelle",en:"Intellectual property"},blocks:[{kind:"p",text:{fr:`Le nom ${e.brand}, son logotype, l’identité graphique du site, ses textes, visuels, animations et son code sont protégés par le droit d’auteur et, le cas échéant, par le droit des marques. Toute reproduction, représentation ou adaptation, totale ou partielle, sans autorisation écrite préalable est interdite (art. L122-4 du Code de la propriété intellectuelle).`,en:`The ${e.brand} name, its logo, the website’s visual identity, texts, images, animations and code are protected by copyright and, where applicable, by trade mark law. Any reproduction, display or adaptation, in whole or in part, without prior written permission is prohibited (art. L122-4 of the French Intellectual Property Code).`}},{kind:"p",text:{fr:"Les marques et contenus de tiers cités ou reproduits sur le site appartiennent à leurs titulaires respectifs.",en:"Third-party trade marks and content mentioned or shown on the website belong to their respective owners."}}]},{id:"liability",title:{fr:"Responsabilité",en:"Liability"},blocks:[{kind:"p",text:{fr:"Les informations publiées sur le site sont vérifiées avec soin, sans garantie qu’elles soient en permanence complètes ou à jour. Les liens vers d’autres sites sont donnés à titre d’information ; leur contenu ne relève pas de la responsabilité de IMPERIUM.",en:"The information published on the website is checked with care, without any guarantee that it is complete or up to date at all times. Links to other websites are provided for information; IMPERIUM is not responsible for their content."}}]},{id:"report",title:{fr:"Signaler un contenu illicite",en:"Reporting illegal content"},blocks:[{kind:"p",text:{fr:`Pour signaler un contenu que vous estimez illicite, présent sur ce site ou sur un site hébergé par IMPERIUM, écrivez à ${d} en indiquant :`,en:`To report content you consider illegal, on this website or on a website hosted by IMPERIUM, write to ${d} and include:`}},{kind:"list",items:[{fr:"votre nom et votre adresse email ;",en:"your name and email address;"},{fr:"l’adresse exacte (URL) du contenu ;",en:"the exact address (URL) of the content;"},{fr:"les raisons pour lesquelles vous le jugez illicite ;",en:"the reasons why you consider it illegal;"},{fr:"une déclaration confirmant que votre signalement est exact et fait de bonne foi.",en:"a statement confirming that your notice is accurate and made in good faith."}]},{kind:"p",text:{fr:"Chaque signalement reçoit un accusé de réception, puis une réponse motivée (règlement (UE) 2022/2065 sur les services numériques, art. 16). Les autorités peuvent utiliser la même adresse, en français ou en anglais (art. 11 et 12).",en:"Each notice is acknowledged, then answered with reasons (Regulation (EU) 2022/2065 on digital services, art. 16). Authorities may use the same address, in French or English (art. 11 and 12)."}}]},{id:"data",title:{fr:"Données personnelles et cookies",en:"Personal data and cookies"},blocks:[{kind:"p",text:{fr:"Le traitement de vos données est décrit dans la [politique de confidentialité](/privacy), qui présente aussi la mesure d’audience du site, sans cookie, et la façon de vous y opposer. Les cookies nécessaires au fonctionnement du site sont listés dans la [politique cookies](/cookies).",en:"How your data is processed is described in the [privacy policy](/privacy), which also covers the website’s audience measurement, without cookies, and how to object to it. The cookies the website needs to work are listed in the [cookie policy](/cookies)."}}]},{id:"law",title:{fr:"Droit applicable",en:"Governing law"},blocks:[{kind:"p",text:{fr:"Le site et les présentes mentions sont soumis au droit français.",en:"The website and this notice are governed by French law."}}]}]},o=`[${e.email}](mailto:${e.email})`,k={dpf:{fr:"Data Privacy Framework UE-États-Unis et clauses contractuelles types",en:"EU-US Data Privacy Framework and standard contractual clauses"},scc:{fr:"Clauses contractuelles types de la Commission européenne",en:"European Commission standard contractual clauses"}},C={id:"privacy",path:"/privacy",title:{fr:"Politique de confidentialité",en:"Privacy policy"},short:{fr:"Confidentialité",en:"Privacy"},updated:c.privacy,essentials:[{fr:`Le responsable du traitement est ${e.denomination} (${e.brand}), joignable à ${o}.`,en:`The controller is ${e.denomination} (${e.brand}), reachable at ${o}.`},{fr:"Nous collectons ce qui sert à vous répondre, à réaliser votre site et à vous facturer, rien de plus.",en:"We collect what is needed to answer you, build your website and invoice you, nothing more."},{fr:"Vos données ne sont ni vendues ni utilisées pour de la publicité.",en:"Your data is never sold or used for advertising."},{fr:"La fréquentation du site est mesurée sans cookie et sans service tiers. Vous pouvez vous y opposer à tout moment, [ci-dessous](#audience).",en:"Traffic to the website is measured without cookies and without any third-party service. You can object to it at any time, [below](#audience)."},{fr:`Vous pouvez accéder à vos données, les corriger, les effacer ou vous opposer à leur traitement en écrivant à ${o}.`,en:`You can access, correct or erase your data, or object to its processing, by writing to ${o}.`}],sections:[{id:"controller",title:{fr:"Responsable du traitement",en:"Controller"},blocks:[{kind:"p",text:{fr:`${e.person}, entrepreneur individuel exerçant sous le nom commercial ${e.brand}, dont l’identité complète figure dans les [mentions légales](/legal-notice). Contact : ${o}, [${e.phone}](${e.phoneHref}).`,en:`${e.person}, sole trader trading as ${e.brand}, whose full identity is given in the [legal notice](/legal-notice). Contact: ${o}, [${e.phone}](${e.phoneHref}).`}},{kind:"p",text:{fr:"Aucun délégué à la protection des données n’a été désigné : toute question relative à vos données peut être adressée à la même adresse.",en:"No data protection officer has been appointed: any question about your data can be sent to the same address."}}]},{id:"processing",title:{fr:"Données traitées, finalités et durées",en:"Data, purposes and retention"},blocks:[{kind:"table",head:[{fr:"Situation",en:"Situation"},{fr:"Données",en:"Data"},{fr:"Finalité",en:"Purpose"},{fr:"Base légale",en:"Legal basis"},{fr:"Conservation",en:"Retention"}],rows:[[{fr:"Message envoyé depuis le site",en:"Message sent from the website"},{fr:"Email, message",en:"Email, message"},{fr:"Vous répondre",en:"Answering you"},{fr:"Intérêt légitime à répondre aux demandes reçues (art. 6.1.f RGPD)",en:"Legitimate interest in answering requests (art. 6(1)(f) GDPR)"},{fr:"3 ans après le dernier échange",en:"3 years after the last exchange"}],[{fr:"Réservation d’un appel",en:"Booking a call"},{fr:"Nom, email, créneau choisi",en:"Name, email, chosen time"},{fr:"Organiser l’appel et créer le lien de visioconférence (Google Agenda, Google Meet)",en:"Organising the call and creating the video link (Google Calendar, Google Meet)"},{fr:"Mesures précontractuelles prises à votre demande (art. 6.1.b)",en:"Pre-contractual steps taken at your request (art. 6(1)(b))"},{fr:"3 ans après le dernier échange",en:"3 years after the last exchange"}],[{fr:"Commande et abonnement",en:"Order and subscription"},{fr:"Prénom, nom, email, entreprise, adresse de facturation, SIRET et numéro de TVA s’ils sont donnés, formule, options, historique des paiements. Les données de carte et d’IBAN sont saisies chez Stripe et ne sont jamais reçues par IMPERIUM.",en:"First name, last name, email, company, billing address, SIRET and VAT number if given, plan, options, payment history. Card and IBAN details are entered with Stripe and never reach IMPERIUM."},{fr:"Conclure et exécuter l’abonnement, facturer",en:"Concluding and performing the subscription, invoicing"},{fr:"Exécution du contrat (art. 6.1.b) et obligations comptables (art. 6.1.c)",en:"Performance of the contract (art. 6(1)(b)) and accounting obligations (art. 6(1)(c))"},{fr:"Durée de l’abonnement, puis 5 ans. Factures : 10 ans",en:"Length of the subscription, then 5 years. Invoices: 10 years"}],[{fr:"Votre compte",en:"Client space"},{fr:"Email de connexion, identifiant Google ou Microsoft si vous les utilisez, codes de connexion, réponses au questionnaire, fichiers, demandes et échanges",en:"Sign-in email, Google or Microsoft identifier if you use them, sign-in codes, questionnaire answers, files, requests and messages"},{fr:"Réaliser et faire évoluer votre site, suivre vos demandes",en:"Building and developing your website, following up your requests"},{fr:"Exécution du contrat (art. 6.1.b)",en:"Performance of the contract (art. 6(1)(b))"},{fr:"Durée de l’abonnement, puis 5 ans. Fichiers déposés : 1 an après la fin de l’abonnement. Codes de connexion : 10 minutes",en:"Length of the subscription, then 5 years. Uploaded files: 1 year after the subscription ends. Sign-in codes: 10 minutes"}],[{fr:"Sécurité du service",en:"Service security"},{fr:"Adresse IP, journaux techniques, tentatives de connexion",en:"IP address, technical logs, sign-in attempts"},{fr:"Protéger le service, prévenir la fraude et les abus",en:"Protecting the service, preventing fraud and abuse"},{fr:"Intérêt légitime (art. 6.1.f)",en:"Legitimate interest (art. 6(1)(f))"},{fr:"12 mois au plus",en:"12 months at most"}],[{fr:"Mesure d’audience",en:"Audience measurement"},{fr:"Pages consultées, domaine du site d’origine, type d’appareil, navigateur et système sans version détaillée, pays, temps de lecture, défilement, temps de chargement, fonctions utilisées. Identifiant du jour calculé sans cookie à partir de l’adresse IP tronquée",en:"Pages viewed, domain of the referring website, device type, browser and system without detailed version, country, reading time, scrolling, loading times, features used. Daily identifier computed without cookies from the truncated IP address"},{fr:"Mesurer la fréquentation et les performances du site pour l’améliorer",en:"Measuring traffic and performance to improve the website"},{fr:"Intérêt légitime (art. 6.1.f), dans le cadre de l’exemption de consentement prévue pour la mesure d’audience, avec un droit d’opposition",en:"Legitimate interest (art. 6(1)(f)), within the consent exemption for audience measurement, with a right to object"},{fr:"Identifiant du jour : 48 heures. Détail : 25 mois. Totaux anonymes : sans limite",en:"Daily identifier: 48 hours. Details: 25 months. Anonymous totals: no limit"}]]},{kind:"p",text:{fr:"Les données marquées comme obligatoires dans les formulaires sont nécessaires pour traiter votre demande ou votre commande. IMPERIUM n’envoie pas de messages publicitaires et ne prend aucune décision fondée exclusivement sur un traitement automatisé.",en:"Data marked as required in the forms is needed to handle your request or order. IMPERIUM sends no advertising messages and makes no decision based solely on automated processing."}}]},{id:"audience",title:{fr:"Mesure d’audience",en:"Audience measurement"},blocks:[{kind:"p",text:{fr:"Pour savoir quelles pages sont lues et si le site fonctionne bien, IMPERIUM mesure sa fréquentation avec son propre outil, sans cookie et sans service tiers. Rien n’est enregistré sur votre appareil pour cette mesure. Elle porte sur :",en:"To know which pages are read and whether the website works well, IMPERIUM measures its traffic with its own tool, without cookies and without any third-party service. Nothing is stored on your device for this measurement. It covers:"}},{kind:"list",items:[{fr:"la page consultée et le site d’où vous venez, réduit à son nom de domaine (par exemple google.com) ;",en:"the page viewed and the website you came from, reduced to its domain name (for example google.com);"},{fr:"le type d’appareil, le navigateur et le système sans leur version détaillée, et le pays ;",en:"the device type, the browser and the system without their detailed version, and the country;"},{fr:"le temps de lecture, le défilement et les temps de chargement de la page ;",en:"the reading time, the scrolling and the page’s loading times;"},{fr:"l’usage de quelques fonctions : réserver un appel, envoyer un message, payer, ouvrir une question, suivre un lien vers un autre site.",en:"the use of a few features: booking a call, sending a message, paying, opening a question, following a link to another website."}]},{kind:"p",text:{fr:"Votre adresse IP n’est jamais enregistrée. Pour compter les visiteurs sans cookie, un identifiant est calculé à partir de votre adresse IP privée de sa dernière partie, de votre navigateur et d’une valeur aléatoire qui change chaque jour et n’est pas conservée. Il ne permet de vous suivre ni d’un jour à l’autre, ni sur d’autres sites, et il est effacé au bout de 48 heures.",en:"Your IP address is never stored. To count visitors without cookies, an identifier is computed from your IP address with its last part removed, your browser, and a random value that changes every day and is not kept. It cannot follow you from one day to the next or across other websites, and it is erased after 48 hours."}},{kind:"p",text:{fr:"Ces données servent uniquement à produire des statistiques pour IMPERIUM. Elles ne sont croisées avec aucune autre donnée, ne servent pas à la publicité et ne sont transmises à personne. Elles sont stockées par Supabase à Paris. Le détail est conservé 25 mois ; au-delà, seuls des totaux anonymes sont gardés.",en:"This data is only used to produce statistics for IMPERIUM. It is not combined with any other data, not used for advertising and not shared with anyone. It is stored by Supabase in Paris. Details are kept for 25 months; beyond that, only anonymous totals are kept."}},{kind:"p",text:{fr:"Cette mesure repose sur l’intérêt légitime de IMPERIUM à connaître la fréquentation de son site et entre dans l’exemption de consentement prévue pour la mesure d’audience (art. 82 de la loi Informatique et Libertés). Vous pouvez vous y opposer à tout moment ci-dessous ; votre choix est gardé sur ce navigateur. Si votre navigateur envoie le signal Global Privacy Control, rien n’est mesuré.",en:"This measurement relies on IMPERIUM’s legitimate interest in knowing how its website is used and falls within the consent exemption for audience measurement (art. 82 of the French Data Protection Act). You can object to it at any time below; your choice is kept in this browser. If your browser sends the Global Privacy Control signal, nothing is measured."}},{kind:"choice"},{kind:"p",text:{fr:"IMPERIUM compte aussi les passages des robots des moteurs de recherche et des assistants d’intelligence artificielle, reconnus à leur nom. Ils ne concernent pas des personnes.",en:"IMPERIUM also counts visits from search engine and artificial intelligence assistant robots, recognised by their name. They do not concern people."}}]},{id:"recipients",title:{fr:"Destinataires et prestataires",en:"Recipients and service providers"},blocks:[{kind:"p",text:{fr:"Vos données sont accessibles aux seules personnes de l’équipe IMPERIUM qui en ont besoin, et aux prestataires ci-dessous, qui agissent sur instruction de IMPERIUM dans le cadre d’un contrat conforme à l’article 28 du RGPD.",en:"Your data is available only to the members of the IMPERIUM team who need it, and to the providers below, who act on IMPERIUM’s instructions under a contract compliant with article 28 GDPR."}},{kind:"table",head:[{fr:"Prestataire",en:"Provider"},{fr:"Rôle",en:"Role"},{fr:"Localisation",en:"Location"},{fr:"Garantie",en:"Safeguard"}],rows:b.map(t=>[{fr:t.name,en:t.name},t.role,t.where,t.id==="supabase"?{fr:"Données stockées dans l’Union européenne ; clauses contractuelles types pour l’assistance",en:"Data stored in the European Union; standard contractual clauses for support access"}:k[t.transfer]])},{kind:"p",text:{fr:"Si vous vous connectez avec Google ou Microsoft, ces sociétés traitent les données de connexion selon leur propre politique. Stripe et PayPal traitent également certaines données de paiement en tant que responsables, notamment pour prévenir la fraude. Vos données ne sont ni vendues ni louées, et ne sont communiquées aux autorités que sur demande légale.",en:"If you sign in with Google or Microsoft, these companies process the sign-in data under their own policy. Stripe and PayPal also process some payment data as controllers, in particular to prevent fraud. Your data is never sold or rented, and is disclosed to authorities only on a lawful request."}}]},{id:"transfers",title:{fr:"Transferts hors de l’Union européenne",en:"Transfers outside the European Union"},blocks:[{kind:"p",text:{fr:"Certains prestataires sont établis aux États-Unis ou y transfèrent des données. Ces transferts reposent sur la décision d’adéquation de la Commission européenne du 10 juillet 2023 (Data Privacy Framework UE-États-Unis) pour les sociétés certifiées, et sur les clauses contractuelles types de la Commission européenne pour les autres. Une copie de ces garanties peut être obtenue sur demande.",en:"Some providers are based in the United States or transfer data there. These transfers rely on the European Commission’s adequacy decision of 10 July 2023 (EU-US Data Privacy Framework) for certified companies, and on the European Commission’s standard contractual clauses for the others. A copy of these safeguards is available on request."}}]},{id:"rights",title:{fr:"Vos droits",en:"Your rights"},blocks:[{kind:"p",text:{fr:"Vous pouvez à tout moment :",en:"At any time, you can:"}},{kind:"list",items:[{fr:"accéder à vos données et en obtenir une copie ;",en:"access your data and obtain a copy;"},{fr:"les faire corriger ou compléter ;",en:"have it corrected or completed;"},{fr:"les faire effacer, sauf lorsque la loi impose leur conservation (factures notamment) ;",en:"have it erased, unless the law requires it to be kept (invoices in particular);"},{fr:"demander la limitation de leur traitement ;",en:"ask for its processing to be restricted;"},{fr:"vous opposer à un traitement fondé sur l’intérêt légitime, dont la [mesure d’audience](#audience) ;",en:"object to processing based on legitimate interest, including [audience measurement](#audience);"},{fr:"recevoir les données que vous avez fournies dans un format lisible par une machine (portabilité) ;",en:"receive the data you provided in a machine-readable format (portability);"},{fr:"définir des directives sur le sort de vos données après votre décès (art. 85 de la loi Informatique et Libertés).",en:"set instructions for your data after your death (art. 85 of the French Data Protection Act)."}]},{kind:"p",text:{fr:`Écrivez à ${o}. Une réponse vous est apportée dans un délai d’un mois, prolongeable de deux mois pour une demande complexe ; un justificatif d’identité peut être demandé en cas de doute raisonnable.`,en:`Write to ${o}. You will receive an answer within one month, which may be extended by two months for a complex request; proof of identity may be requested in case of reasonable doubt.`}},{kind:"p",text:{fr:"Vous pouvez aussi introduire une réclamation auprès de la CNIL, 3 place de Fontenoy, TSA 80715, 75334 Paris Cedex 07, [www.cnil.fr](https://www.cnil.fr).",en:"You may also lodge a complaint with the CNIL, the French data protection authority, 3 place de Fontenoy, TSA 80715, 75334 Paris Cedex 07, France, [www.cnil.fr](https://www.cnil.fr), or with the authority of the country where you live."}}]},{id:"security",title:{fr:"Sécurité",en:"Security"},blocks:[{kind:"p",text:{fr:"Les échanges sont chiffrés (HTTPS). Chaque client n’accède qu’à ses propres projets, avec un code à usage unique ou un compte Google ou Microsoft. L’administration est réservée à l’équipe IMPERIUM, par un compte Google vérifié. En cas de violation de données présentant un risque pour vous, vous en êtes informé dans les conditions prévues par le RGPD.",en:"Traffic is encrypted (HTTPS). Each client can only reach their own projects, with a one-time code or a Google or Microsoft account. Administration is restricted to the IMPERIUM team, through a verified Google account. If a data breach puts you at risk, you will be informed as provided by the GDPR."}}]},{id:"client-sites",title:{fr:"Visiteurs des sites de nos clients",en:"Visitors to our clients’ websites"},blocks:[{kind:"p",text:{fr:"Lorsque IMPERIUM héberge et maintient le site d’un client, les données des visiteurs de ce site sont traitées pour le compte du client, qui en est responsable (voir les [conditions générales de vente](/terms#processing)). Pour exercer vos droits, adressez-vous d’abord à l’éditeur du site concerné.",en:"When IMPERIUM hosts and maintains a client’s website, the data of that website’s visitors is processed on behalf of the client, who is the controller (see the [terms of sale](/terms#processing)). To exercise your rights, contact the publisher of that website first."}}]},{id:"changes",title:{fr:"Modifications",en:"Changes"},blocks:[{kind:"p",text:{fr:"Cette politique peut évoluer. La date de la version en vigueur figure en haut de la page ; en cas de changement important, les clients en sont prévenus par email.",en:"This policy may change. The date of the version in force is shown at the top of the page; clients are notified by email of any significant change."}}]}]},s=`[${e.email}](mailto:${e.email})`,f=()=>v.consumers,h=()=>!0,I={id:"terms",path:"/terms",title:{fr:"Conditions générales de vente",en:"Terms of sale"},short:{fr:"CGV",en:"Terms"},updated:c.terms,essentials:[{fr:"L’offre est réservée aux professionnels.",en:"The offer is for professionals only."},{fr:"L’abonnement est mensuel et sans engagement : vous pouvez le résilier à tout moment depuis votre espace client, pour la fin de la période en cours.",en:"The subscription is monthly with no minimum term: you can cancel it at any time from your client space, effective at the end of the current period."},{fr:"Votre site est en ligne 10 jours ouvrés après réception du questionnaire complet. Chaque mois de retard vous est remboursé.",en:"Your website goes live 10 working days after we receive the completed questionnaire. Every month of delay is refunded."},{fr:"Après 12 mensualités réglées, le site et ses fichiers vous sont transférés. Si vous partez avant, vous pouvez régler les mensualités restantes pour les obtenir.",en:"After 12 paid monthly payments, the website and its files are transferred to you. If you leave earlier, you can pay the remaining monthly payments to get them."},{fr:"Votre nom de domaine vous appartient, quoi qu’il arrive.",en:"Your domain name is yours, whatever happens."}],sections:[{id:"scope",title:{fr:"Objet et champ d’application",en:"Scope"},blocks:[{kind:"p",text:{fr:`Les présentes conditions générales de vente (les « Conditions ») régissent les abonnements souscrits auprès de ${e.person}, entrepreneur individuel exerçant sous le nom commercial ${e.brand}, SIREN ${e.siren} (« IMPERIUM »), dont l’identité complète figure dans les [mentions légales](/legal-notice), joignable à ${s} et au [${e.phone}](${e.phoneHref}).`,en:`These terms of sale (the “Terms”) govern subscriptions taken out with ${e.person}, a sole trader (French “entrepreneur individuel”) trading as ${e.brand}, SIREN ${e.siren} (“IMPERIUM”), whose full identity is given in the [legal notice](/legal-notice), reachable at ${s} and on [${e.phone}](${e.phoneHref}).`}},{kind:"p",when:h,text:{fr:"L’offre est réservée aux professionnels : entreprises, indépendants, professions libérales et associations qui souscrivent pour les besoins de leur activité (le « Client »). En commandant, le Client déclare agir à des fins professionnelles.",en:"The offer is for professionals only: companies, freelancers, professional practices and associations subscribing for the needs of their activity (the “Client”). By ordering, the Client confirms that it is acting for professional purposes."}},{kind:"p",when:f,text:{fr:"L’offre est ouverte aux professionnels et aux consommateurs (le « Client »). Les dispositions propres aux consommateurs figurent à [l’article 13](#consumers).",en:"The offer is open to professionals and consumers (the “Client”). The provisions specific to consumers are set out in [article 13](#consumers)."}},{kind:"p",text:{fr:"Les Conditions sont acceptées lors de la commande et prévalent sur tout autre document du Client. La version applicable est celle en vigueur le jour de la commande ; IMPERIUM la conserve et la communique sur simple demande.",en:"The Terms are accepted when ordering and prevail over any other document of the Client. The applicable version is the one in force on the day of the order; IMPERIUM keeps it and provides it on request."}}]},{id:"definitions",title:{fr:"Définitions",en:"Definitions"},blocks:[{kind:"list",items:[{fr:"**Site** : le site internet conçu, mis en ligne, hébergé et maintenu par IMPERIUM pour le Client.",en:"**Website**: the website designed, put online, hosted and maintained by IMPERIUM for the Client."},{fr:"**Abonnement** : le contrat conclu pour une formule et, le cas échéant, des options, payé chaque mois.",en:"**Subscription**: the contract for a plan and, where chosen, options, paid every month."},{fr:"**Mensualité** : le montant facturé pour une période mensuelle de l’Abonnement.",en:"**Monthly payment**: the amount invoiced for one monthly period of the Subscription."},{fr:"**Évolution** : une modification ou une amélioration ciblée du Site après sa mise en ligne, par exemple faire évoluer une section, modifier un contenu, améliorer un parcours, ajouter un élément ou intégrer un outil.",en:"**Improvement**: a targeted change or improvement to the Website after it goes live, for example reworking a section, changing content, improving a user journey, adding an element or connecting a tool."},{fr:"**Espace client** : l’espace en ligne où le Client suit son projet, transmet ses demandes et gère son Abonnement.",en:"**Client space**: the online area where the Client follows the project, sends requests and manages the Subscription."},{fr:"**Jour ouvré** : du lundi au vendredi, hors jours fériés en France métropolitaine.",en:"**Working day**: Monday to Friday, excluding public holidays in mainland France."},{fr:"**Livrables** : les créations réalisées spécifiquement pour le Client : maquettes, pages, textes rédigés par IMPERIUM, code propre au Site et, avec l’option Identité visuelle, le logotype, la palette, les typographies retenues et le kit graphique.",en:"**Deliverables**: the work created specifically for the Client: designs, pages, texts written by IMPERIUM, the Website’s own code and, with the Brand Identity option, the logo, palette, chosen typefaces and brand kit."}]}]},{id:"plans",title:{fr:"Formules et options",en:"Plans and options"},blocks:[{kind:"p",text:{fr:"Le contenu de chaque formule et de chaque option est décrit sur la page d’accueil du site au moment de la commande et rappelé dans le récapitulatif avant paiement. Toutes les formules comprennent la conception d’un Site sur mesure, sa mise en ligne, un nom de domaine, l’hébergement et la maintenance technique.",en:"The content of each plan and option is described on the website’s home page at the time of the order and shown again in the summary before payment. Every plan includes the design of a bespoke Website, putting it online, a domain name, hosting and technical maintenance."}},{kind:"list",items:[{fr:"**Présence** : 1 Évolution par mois, support sous 48 heures ouvrées, statistiques essentielles.",en:"**Presence**: 1 Improvement per month, support within 48 working hours, essential statistics."},{fr:"**Croissance** : 2 Évolutions par mois et, en plus de Présence, référencement et visibilité dans les outils d’intelligence artificielle, suivi des conversions, intégrations marketing, analyses et recommandations.",en:"**Growth**: 2 Improvements per month and, on top of Presence, search and AI visibility work, conversion tracking, marketing integrations, analysis and recommendations."},{fr:"**Partenaire** : 4 Évolutions par mois et, en plus de Croissance, pages de campagne, optimisation des conversions, automatisations et intégrations, support prioritaire.",en:"**Partner**: 4 Improvements per month and, on top of Growth, campaign pages, conversion improvements, automations and integrations, priority support."}]},{kind:"p",text:{fr:"Les options sont : **Identité visuelle** (logotype, palette de couleurs, typographies, kit graphique), facturée pendant 12 Mensualités au plus puis retirée automatiquement de la facturation ; **Visibilité Google locale** (fiche Google, Google Maps, mises à jour, suivi des performances) ; **Site multilingue**, facturée par langue supplémentaire.",en:"The options are: **Brand Identity** (logo, palette, typefaces, brand kit), invoiced for 12 Monthly payments at most and then removed from billing automatically; **Local Google Visibility** (Google Business Profile, Google Maps, updates, performance tracking); **Multilingual Website**, invoiced per additional language."}},{kind:"p",text:{fr:"Les Évolutions d’une période mensuelle ne se reportent pas sur les périodes suivantes. Une demande plus large qu’une Évolution peut, avec l’accord du Client, être réalisée en plusieurs Évolutions.",en:"Improvements in a monthly period do not carry over to later periods. A request larger than one Improvement may, with the Client’s agreement, be carried out as several Improvements."}},{kind:"p",text:{fr:"Le travail de référencement et de visibilité crée les meilleures conditions pour que le Site soit trouvé. Il ne garantit ni une position dans un moteur de recherche, ni une citation par un outil d’intelligence artificielle, ni un volume de visites ou de ventes.",en:"Search and visibility work creates the best conditions for the Website to be found. It does not guarantee any ranking in a search engine, any mention by an artificial intelligence tool, or any volume of visits or sales."}},{kind:"p",text:{fr:"Le nom de domaine inclus est un nom disponible dans une extension courante (par exemple .fr, .com ou .eu), au tarif standard du registre. Un nom proposé à un prix supérieur (nom premium ou revente) fait l’objet d’un accord préalable sur son coût.",en:"The included domain name is an available name in a common extension (for example .fr, .com or .eu), at the registry’s standard price. A name offered at a higher price (premium or resale) requires prior agreement on its cost."}}]},{id:"order",title:{fr:"Commande",en:"Ordering"},blocks:[{kind:"p",text:{fr:"Le Client choisit sa formule et ses options, renseigne ses informations, choisit son moyen de paiement puis vérifie le récapitulatif : formule, options et montant mensuel. Il passe commande en confirmant le paiement. L’Abonnement est conclu dès que le paiement de la première Mensualité est accepté ; le Client en reçoit la confirmation par email, avec le récapitulatif et la facture.",en:"The Client chooses a plan and options, enters its details, chooses a payment method and checks the summary: plan, options and monthly amount. The order is placed by confirming the payment. The Subscription is concluded as soon as payment of the first Monthly payment is accepted; the Client receives confirmation by email, with the summary and the invoice."}},{kind:"p",text:{fr:"Le Client garantit l’exactitude des informations transmises. Une même adresse email ne peut porter qu’un seul Abonnement actif ; pour un second site, le Client contacte IMPERIUM.",en:"The Client guarantees that the information provided is accurate. One email address can only hold one active Subscription; for a second website, the Client contacts IMPERIUM."}},{kind:"p",text:{fr:"IMPERIUM peut refuser une commande pour un motif légitime, notamment un litige de paiement antérieur ou une activité contraire à la loi. Toute somme déjà encaissée est alors remboursée intégralement.",en:"IMPERIUM may refuse an order for a legitimate reason, in particular an earlier payment dispute or an unlawful activity. Any amount already collected is then refunded in full."}}]},{id:"prices",title:{fr:"Prix et paiement",en:"Prices and payment"},blocks:[{kind:"p",text:{fr:`Les prix sont affichés par mois, en euros, en dollars américains ou en livres sterling selon la version du site choisie. IMPERIUM relève de la franchise en base de TVA (${u.fr}) : aucune TVA n’est facturée. Le Client établi hors de France qui serait redevable d’une taxe dans son pays l’acquitte selon les règles qui lui sont applicables, notamment l’autoliquidation.`,en:`Prices are shown per month, in euros, US dollars or pounds sterling depending on the version of the website. IMPERIUM is under the French VAT exemption for small businesses (${u.en}): no VAT is charged. A Client established outside France who owes a tax in its own country pays it under the rules that apply to it, such as the reverse charge.`}},{kind:"p",text:{fr:"Le paiement s’effectue par carte bancaire, prélèvement SEPA (en euros), PayPal ou portefeuille électronique, par l’intermédiaire de Stripe. La première Mensualité est payée à la commande ; les suivantes sont prélevées automatiquement chaque mois à la date anniversaire de la souscription. Une facture est émise à chaque échéance et reste disponible dans l’Espace client.",en:"Payment is made by card, SEPA Direct Debit (in euros), PayPal or digital wallet, through Stripe. The first Monthly payment is paid when ordering; the following ones are collected automatically every month on the subscription’s anniversary date. An invoice is issued for each payment and remains available in the Client space."}},{kind:"p",text:{fr:"IMPERIUM peut modifier ses prix. Un nouveau prix ne s’applique à un Abonnement en cours qu’après avoir été notifié par email au moins 30 jours avant l’échéance concernée ; le Client qui le refuse peut résilier avant cette échéance.",en:"IMPERIUM may change its prices. A new price only applies to an ongoing Subscription after being notified by email at least 30 days before the payment concerned; a Client who refuses it may cancel before that date."}},{kind:"p",text:{fr:"En cas d’échec d’un paiement, de nouvelles tentatives sont effectuées et le Client en est informé. Sans régularisation dans les 15 jours suivant l’échéance, IMPERIUM peut suspendre les Évolutions et l’accompagnement ; sans régularisation 8 jours après une mise en demeure envoyée par email, IMPERIUM peut résilier l’Abonnement.",en:"If a payment fails, new attempts are made and the Client is informed. Without settlement within 15 days of the due date, IMPERIUM may suspend Improvements and support; without settlement 8 days after a formal notice sent by email, IMPERIUM may terminate the Subscription."}},{kind:"p",text:{fr:"Toute somme impayée à son échéance porte de plein droit des pénalités de retard au taux d’intérêt appliqué par la Banque centrale européenne à son opération de refinancement la plus récente, majoré de 10 points, ainsi qu’une indemnité forfaitaire pour frais de recouvrement de 40 € (art. L441-10 du Code de commerce). Aucun escompte n’est accordé pour paiement anticipé.",en:"Any amount unpaid on its due date automatically bears late payment interest at the European Central Bank’s most recent refinancing rate plus 10 points, and a fixed recovery fee of €40 (art. L441-10 of the French Commercial Code). No discount is given for early payment."}}]},{id:"delivery",title:{fr:"Réalisation et mise en ligne",en:"Building and launching the website"},blocks:[{kind:"p",text:{fr:"Après la commande, le Client répond au questionnaire de son Espace client (environ 5 minutes) : activité, objectifs, préférences et contenus disponibles. À partir de ces réponses, IMPERIUM conçoit une première proposition, que le Client commente ; IMPERIUM l’ajuste, puis teste et met le Site en ligne.",en:"After ordering, the Client answers the questionnaire in the Client space (about 5 minutes): activity, goals, preferences and available content. From these answers, IMPERIUM designs a first proposal, which the Client reviews; IMPERIUM adjusts it, then tests the Website and puts it online."}},{kind:"p",text:{fr:"IMPERIUM met le Site en ligne dans un délai de 10 Jours ouvrés à compter du Jour ouvré qui suit la réception du questionnaire complet. Les jours pendant lesquels IMPERIUM attend une réponse, un contenu, un accès ou une validation du Client ne sont pas décomptés.",en:"IMPERIUM puts the Website online within 10 Working days from the Working day after receiving the completed questionnaire. Days on which IMPERIUM is waiting for an answer, content, access or approval from the Client are not counted."}},{kind:"p",text:{fr:"La mise en ligne a lieu à l’adresse du nom de domaine du Client. Lorsque ce nom n’est pas encore utilisable pour une raison qui ne dépend pas de IMPERIUM (transfert en cours, accès non fourni), le Site est mis en ligne à une adresse provisoire, ce qui vaut mise en ligne pour le calcul du délai.",en:"The Website goes live at the Client’s domain name. When that name cannot be used yet for a reason outside IMPERIUM’s control (transfer in progress, access not provided), the Website goes live at a temporary address, which counts as going live for the deadline."}},{kind:"p",text:{fr:"Le Client vérifie le Site après sa mise en ligne et signale toute anomalie depuis son Espace client. IMPERIUM corrige sans frais les anomalies qui lui sont imputables, sans que la correction compte comme une Évolution.",en:"The Client checks the Website once it is live and reports any defect from the Client space. IMPERIUM fixes defects attributable to it free of charge, and a fix does not count as an Improvement."}}]},{id:"delay",title:{fr:"Garantie de délai",en:"Delivery guarantee"},blocks:[{kind:"p",text:{fr:"Si le Site n’est pas mis en ligne dans le délai de 10 Jours ouvrés prévu à [l’article 6](#delivery), IMPERIUM rembourse intégralement la Mensualité de la période mensuelle en cours. Si le retard se prolonge sur la période mensuelle suivante, ne serait-ce que d’un jour, la Mensualité de cette période est également remboursée, et ainsi de suite jusqu’à la mise en ligne.",en:"If the Website is not online within the 10 Working days set in [article 6](#delivery), IMPERIUM refunds in full the Monthly payment of the current monthly period. If the delay runs into the next monthly period, even by one day, the Monthly payment for that period is refunded as well, and so on until the Website is online."}},{kind:"p",text:{fr:"Le remboursement est fait sur le moyen de paiement utilisé, sans démarche du Client, dans les 14 jours suivant la fin du délai ou le début de la période concernée. Le Site reste livré, l’Abonnement se poursuit, et une Mensualité remboursée à ce titre compte comme réglée pour le transfert prévu à [l’article 10](#ip). Le Client peut résilier à tout moment ([article 12](#term)).",en:"The refund is made to the payment method used, with no action needed from the Client, within 14 days after the deadline or the start of the period concerned. The Website is still delivered, the Subscription continues, and a Monthly payment refunded under this guarantee counts as paid for the transfer in [article 10](#ip). The Client may cancel at any time ([article 12](#term))."}},{kind:"p",text:{fr:"La garantie ne s’applique pas lorsque le retard est dû au Client (questionnaire incomplet, réponses, contenus ou accès attendus) ou à un cas de force majeure.",en:"The guarantee does not apply when the delay is caused by the Client (incomplete questionnaire, answers, content or access still awaited) or by force majeure."}}]},{id:"service",title:{fr:"Accompagnement mensuel",en:"Monthly service"},blocks:[{kind:"p",text:{fr:"Après la mise en ligne, le Client transmet ses demandes d’Évolution depuis son Espace client. IMPERIUM les réalise par ordre de priorité, dans la limite des Évolutions de sa formule pour la période en cours.",en:"Once the Website is online, the Client sends Improvement requests from the Client space. IMPERIUM carries them out in order of priority, within the number of Improvements of the plan for the current period."}},{kind:"p",text:{fr:"Le support répond sous 48 heures ouvrées, et en priorité pour la formule Partenaire. IMPERIUM héberge le Site, en assure la maintenance technique et la sécurité, et met en œuvre les moyens raisonnables pour qu’il reste accessible. Des interruptions peuvent survenir pour maintenance ou du fait des prestataires techniques ; IMPERIUM s’efforce de les limiter et prévient le Client de celles qui sont programmées.",en:"Support answers within 48 working hours, with priority for the Partner plan. IMPERIUM hosts the Website, handles its technical maintenance and security, and uses reasonable means to keep it available. Interruptions may occur for maintenance or because of technical providers; IMPERIUM works to keep them short and gives notice of planned ones."}},{kind:"p",text:{fr:"Les prestations de IMPERIUM relèvent d’une obligation de moyens.",en:"IMPERIUM’s services are provided under a best-efforts obligation."}}]},{id:"client",title:{fr:"Engagements du Client",en:"Client’s commitments"},blocks:[{kind:"p",text:{fr:"Le Client s’engage à :",en:"The Client undertakes to:"}},{kind:"list",items:[{fr:"fournir des informations exactes et répondre dans un délai raisonnable aux demandes utiles à la réalisation ;",en:"provide accurate information and answer requests needed for the work within a reasonable time;"},{fr:"disposer des droits sur les contenus qu’il transmet (textes, images, logos, marques, vidéos) et garantir IMPERIUM contre toute réclamation de tiers à leur sujet ;",en:"hold the rights to the content it provides (texts, images, logos, trade marks, videos) and indemnify IMPERIUM against any third-party claim about them;"},{fr:"exercer une activité licite et ne pas demander la publication de contenus illicites ;",en:"carry on a lawful activity and not ask for illegal content to be published;"},{fr:"garder confidentiels ses moyens de connexion à l’Espace client.",en:"keep its Client space sign-in details confidential."}]},{kind:"p",text:{fr:"Le Client est l’éditeur de son Site : il est responsable des contenus publiés et des informations légales qui le concernent (mentions légales, politique de confidentialité, conditions de vente). IMPERIUM intègre ces éléments à sa demande, sans en vérifier la conformité.",en:"The Client is the publisher of its Website: it is responsible for the content published and for its own legal information (legal notice, privacy policy, terms of sale). IMPERIUM adds these items at the Client’s request, without checking their compliance."}}]},{id:"ip",title:{fr:"Propriété intellectuelle et transfert du Site",en:"Intellectual property and transfer of the Website"},blocks:[{kind:"p",text:{fr:"**Pendant l’Abonnement.** IMPERIUM reste titulaire des droits sur le Site et les Livrables. Le Client dispose d’un droit d’utilisation non exclusif du Site pour son activité, pendant la durée de l’Abonnement. Les contenus fournis par le Client restent sa propriété ; il autorise IMPERIUM à les utiliser pour réaliser, héberger et faire évoluer le Site.",en:"**During the Subscription.** IMPERIUM holds the rights to the Website and the Deliverables. The Client has a non-exclusive right to use the Website for its activity for the length of the Subscription. Content provided by the Client remains its property; the Client allows IMPERIUM to use it to build, host and develop the Website."}},{kind:"p",text:{fr:"**Après 12 Mensualités réglées.** À l’issue de la douzième période mensuelle, dès lors que 12 Mensualités ont été réglées, IMPERIUM cède au Client, à titre exclusif, les droits patrimoniaux d’auteur sur les Livrables : droits de reproduction, de représentation, d’adaptation et de modification, sur tout support, pour le monde entier et pour toute la durée légale de protection. Le prix de cette cession est compris dans les Mensualités. Le Client peut alors demander la remise des fichiers du Site (code source, médias et fichiers de création des Livrables), transmis dans un délai de 15 Jours ouvrés. L’Abonnement peut se poursuivre ; les Livrables créés ensuite sont cédés dans les mêmes conditions dès le règlement de la Mensualité de la période où ils sont livrés.",en:"**After 12 paid Monthly payments.** At the end of the twelfth monthly period, once 12 Monthly payments have been paid, IMPERIUM assigns to the Client, exclusively, the economic copyright in the Deliverables: the rights to reproduce, display, adapt and modify them, on any medium, worldwide and for the full legal term of protection. The price of this assignment is included in the Monthly payments. The Client may then ask for the Website’s files (source code, media and design files of the Deliverables), delivered within 15 Working days. The Subscription may continue; Deliverables created afterwards are assigned on the same terms once the Monthly payment for the period in which they are delivered has been paid."}},{kind:"p",text:{fr:"**En cas de départ avant 12 Mensualités.** Le Client qui résilie avant d’avoir réglé 12 Mensualités choisit l’une des deux options suivantes :",en:"**Leaving before 12 Monthly payments.** A Client who cancels before having paid 12 Monthly payments chooses one of the following two options:"}},{kind:"list",ordered:!0,items:[{fr:"régler les Mensualités restantes pour atteindre 12 Mensualités, au montant de sa dernière Mensualité (formule et options) : la cession intervient au paiement et les fichiers lui sont remis. Par exemple, après 4 Mensualités de 128 €, il reste 8 × 128 € = 1 024 € à régler ;",en:"pay the remaining Monthly payments up to 12, at the amount of its last Monthly payment (plan and options): the assignment takes effect on payment and the files are delivered. For example, after 4 Monthly payments of €128, 8 × €128 = €1,024 remains to be paid;"},{fr:"partir sans les fichiers du Site ni les droits sur les Livrables : le Site est mis hors ligne à la fin de la dernière période réglée et IMPERIUM conserve ses droits.",en:"leave without the Website’s files or the rights to the Deliverables: the Website is taken offline at the end of the last paid period and IMPERIUM keeps its rights."}]},{kind:"p",text:{fr:"Sans choix exprimé avant la fin de la dernière période réglée, la seconde option s’applique. Dans les deux cas, le Client conserve son nom de domaine ([article 11](#domain)) et récupère sur demande les contenus qu’il a fournis.",en:"If no choice is made before the end of the last paid period, the second option applies. Either way, the Client keeps its domain name ([article 11](#domain)) and gets back, on request, the content it provided."}},{kind:"p",text:{fr:"**Éléments de tiers et savoir-faire.** Les composants de tiers intégrés au Site (bibliothèques open source, polices de caractères, images ou services sous licence) restent soumis à leurs propres licences, que le Client respecte. Les outils, méthodes et savoir-faire généraux de IMPERIUM, qui ne sont pas propres au Site, ne sont pas cédés ; le Client reçoit, sans limite de durée, le droit de les utiliser pour faire fonctionner le Site.",en:"**Third-party items and know-how.** Third-party components in the Website (open source libraries, typefaces, licensed images or services) remain under their own licences, which the Client complies with. IMPERIUM’s general tools, methods and know-how, which are not specific to the Website, are not assigned; the Client receives, without time limit, the right to use them to run the Website."}},{kind:"p",text:{fr:"**Fin à l’initiative de IMPERIUM.** Si IMPERIUM met fin à l’Abonnement sans manquement du Client, le Client obtient la cession et la remise des fichiers sans autre paiement.",en:"**Termination by IMPERIUM.** If IMPERIUM ends the Subscription while the Client is not in breach, the Client receives the assignment and the files without any further payment."}}]},{id:"domain",title:{fr:"Nom de domaine",en:"Domain name"},blocks:[{kind:"p",text:{fr:"Le nom de domaine du Site appartient au Client. IMPERIUM l’enregistre au nom du Client, qui en est le titulaire ; lorsque ce n’est pas possible, IMPERIUM le détient pour le compte du Client et le lui transfère gratuitement, sur simple demande, à tout moment.",en:"The Website’s domain name belongs to the Client. IMPERIUM registers it in the Client’s name, as its holder; where this is not possible, IMPERIUM holds it on the Client’s behalf and transfers it free of charge, on request, at any time."}},{kind:"p",text:{fr:"Les frais d’enregistrement et de renouvellement sont compris dans l’Abonnement pendant sa durée. À la fin de l’Abonnement, quelle qu’en soit la cause, IMPERIUM remet au Client le code de transfert et les accès nécessaires ; le renouvellement est ensuite à la charge du Client. Un nom de domaine que le Client possédait déjà reste le sien ; il donne à IMPERIUM les accès techniques nécessaires à la mise en ligne.",en:"Registration and renewal fees are included in the Subscription while it runs. When the Subscription ends, for whatever reason, IMPERIUM gives the Client the transfer code and the necessary access; renewal is then at the Client’s expense. A domain name the Client already owned remains its own; the Client gives IMPERIUM the technical access needed to put the Website online."}}]},{id:"term",title:{fr:"Durée et résiliation",en:"Term and cancellation"},blocks:[{kind:"p",text:{fr:"L’Abonnement est conclu sans durée minimale d’engagement. Il se renouvelle automatiquement chaque mois.",en:"The Subscription has no minimum term. It renews automatically every month."}},{kind:"p",text:{fr:`Le Client peut résilier à tout moment depuis son Espace client (rubrique Abonnement) ou en écrivant à ${s}. La résiliation prend effet à la fin de la période mensuelle en cours, déjà payée : aucune Mensualité n’est ensuite prélevée et la période commencée n’est pas remboursée. Les prestations continuent jusqu’à cette date. Une confirmation indiquant la date d’effet est envoyée par email.`,en:`The Client may cancel at any time from the Client space (Subscription section) or by writing to ${s}. Cancellation takes effect at the end of the current monthly period, which is already paid: no further Monthly payment is collected and the period already started is not refunded. Services continue until that date. A confirmation stating the effective date is sent by email.`}},{kind:"p",text:{fr:"IMPERIUM peut mettre fin à l’Abonnement avec un préavis de 30 jours notifié par email. IMPERIUM peut aussi le résilier en cas de manquement grave du Client, notamment un défaut de paiement persistant ([article 5](#prices)) ou une demande de publication de contenus illicites, après une mise en demeure restée sans effet pendant 8 jours lorsque le manquement peut être réparé.",en:"IMPERIUM may end the Subscription with 30 days’ notice sent by email. IMPERIUM may also terminate it for a serious breach by the Client, in particular persistent non-payment ([article 5](#prices)) or a request to publish illegal content, after a formal notice left unanswered for 8 days where the breach can be remedied."}},{kind:"p",text:{fr:"À la fin de l’Abonnement, le Site est mis hors ligne, sauf s’il a été transféré au Client ([article 10](#ip)). Les données sont ensuite conservées puis supprimées comme le prévoit la [politique de confidentialité](/privacy).",en:"When the Subscription ends, the Website is taken offline unless it has been transferred to the Client ([article 10](#ip)). Data is then kept and deleted as set out in the [privacy policy](/privacy)."}}]},{id:"withdrawal",when:h,title:{fr:"Droit de rétractation",en:"Right of withdrawal"},blocks:[{kind:"p",text:{fr:"Le contrat étant conclu à distance entre professionnels, le droit de rétractation prévu par le Code de la consommation ne s’applique pas. L’Abonnement reste sans engagement et résiliable à tout moment ([article 12](#term)).",en:"As the contract is concluded at a distance between professionals, the right of withdrawal under the French Consumer Code does not apply. The Subscription still has no minimum term and can be cancelled at any time ([article 12](#term))."}}]},{id:"consumers",when:f,title:{fr:"Clients consommateurs",en:"Consumer clients"},blocks:[{kind:"p",text:{fr:"Le présent article s’applique au Client consommateur, ainsi qu’au professionnel employant au plus cinq salariés qui souscrit hors établissement un contrat n’entrant pas dans le champ de son activité principale (art. L221-3 du Code de la consommation).",en:"This article applies to a consumer Client, and to a professional with five employees or fewer who subscribes off-premises to a contract outside the scope of its main activity (art. L221-3 of the French Consumer Code)."}},{kind:"p",text:{fr:`**Rétractation.** Le Client dispose de 14 jours à compter de la conclusion de l’Abonnement pour se rétracter, sans motif, en écrivant à ${s} ou en utilisant le modèle ci-dessous. S’il a demandé que la réalisation commence avant la fin de ce délai, il règle un montant proportionnel au service fourni jusqu’à sa rétractation (art. L221-25). Le remboursement intervient dans les 14 jours, par le moyen de paiement utilisé.`,en:`**Withdrawal.** The Client has 14 days from the conclusion of the Subscription to withdraw, without giving a reason, by writing to ${s} or using the model below. If the Client asked for the work to start before the end of that period, it pays an amount in proportion to the service provided until withdrawal (art. L221-25). The refund is made within 14 days, to the payment method used.`}},{kind:"p",text:{fr:`Modèle de formulaire : « À l’attention de ${e.denomination} (${e.brand}), ${e.street}, ${e.postalCode} ${e.city}, ${e.email}. Je vous notifie par la présente ma rétractation du contrat portant sur l’abonnement ci-dessous. Souscrit le : … Nom : … Adresse : … Date et signature (en cas d’envoi papier) : … »`,en:`Model form: “To ${e.denomination} (${e.brand}), ${e.street}, ${e.postalCode} ${e.city}, France, ${e.email}. I hereby give notice that I withdraw from the contract for the subscription below. Subscribed on: … Name: … Address: … Date and signature (if sent on paper): …”`}},{kind:"p",text:{fr:"**Garantie légale de conformité.** Le Client bénéficie de la garantie légale de conformité des contenus et services numériques (art. L224-25-12 et suivants du Code de la consommation) : IMPERIUM répond des défauts de conformité du Site qui apparaissent pendant la durée de l’Abonnement. Le Client obtient la mise en conformité sans frais ou, à défaut, une réduction du prix ou la résolution du contrat.",en:"**Legal guarantee of conformity.** The Client benefits from the legal guarantee of conformity for digital content and services (art. L224-25-12 and following of the French Consumer Code): IMPERIUM is liable for any lack of conformity of the Website that appears during the Subscription. The Client is entitled to have it brought into conformity free of charge or, failing that, to a price reduction or termination of the contract."}},{kind:"p",text:{fr:"**Médiation.** En cas de litige non résolu par écrit avec IMPERIUM, le Client peut recourir gratuitement au médiateur de la consommation : .",en:"**Mediation.** If a dispute is not settled in writing with IMPERIUM, the Client may refer it free of charge to the consumer mediator: ."}}]},{id:"liability",title:{fr:"Responsabilité",en:"Liability"},blocks:[{kind:"p",text:{fr:"IMPERIUM répond des dommages directs résultant d’un manquement prouvé à ses obligations. IMPERIUM ne répond pas des dommages indirects, tels qu’une perte de chiffre d’affaires, de clientèle ou d’image, ni des conséquences des contenus fournis par le Client, ni des défaillances de services tiers (registres de noms de domaine, hébergeur, prestataires de paiement) qui ne lui sont pas imputables.",en:"IMPERIUM is liable for direct damage resulting from a proven breach of its obligations. IMPERIUM is not liable for indirect damage, such as loss of revenue, customers or reputation, for the consequences of content provided by the Client, or for failures of third-party services (domain registries, host, payment providers) not attributable to it."}},{kind:"p",text:{fr:"Sauf faute lourde ou intentionnelle, la responsabilité totale de IMPERIUM au titre de l’Abonnement est limitée au montant des Mensualités payées par le Client au cours des 12 mois précédant le fait générateur.",en:"Except in the event of gross negligence or wilful misconduct, IMPERIUM’s total liability under the Subscription is limited to the Monthly payments made by the Client in the 12 months before the event giving rise to it."}}]},{id:"processing",title:{fr:"Données personnelles traitées pour le Client",en:"Personal data processed for the Client"},blocks:[{kind:"p",text:{fr:"Chaque partie respecte la réglementation sur la protection des données, notamment le règlement (UE) 2016/679 (RGPD). Les données du Client et de ses interlocuteurs sont traitées par IMPERIUM selon sa [politique de confidentialité](/privacy).",en:"Each party complies with data protection law, in particular Regulation (EU) 2016/679 (GDPR). Data about the Client and its contacts is processed by IMPERIUM under its [privacy policy](/privacy)."}},{kind:"p",text:{fr:"Pour héberger et maintenir le Site, IMPERIUM traite pour le compte du Client, et sur ses instructions, les données des visiteurs du Site, par exemple les messages envoyés par un formulaire. Le Client est responsable de ces traitements et IMPERIUM en est sous-traitant au sens de l’article 28 du RGPD, dans les conditions suivantes :",en:"When hosting and maintaining the Website, IMPERIUM processes the data of the Website’s visitors on the Client’s behalf and instructions, for example messages sent through a form. The Client is the controller of this processing and IMPERIUM is its processor within the meaning of article 28 GDPR, on the following terms:"}},{kind:"list",items:[{fr:"objet et durée : hébergement, maintenance et évolution du Site, pendant l’Abonnement ;",en:"subject matter and duration: hosting, maintenance and development of the Website, for the length of the Subscription;"},{fr:"données et personnes concernées : celles que le Site recueille auprès de ses visiteurs, selon les fonctions choisies par le Client ;",en:"data and data subjects: those the Website collects from its visitors, depending on the features the Client chooses;"},{fr:"IMPERIUM ne traite ces données que sur instruction documentée du Client, garantit la confidentialité des personnes autorisées à y accéder et met en œuvre des mesures de sécurité adaptées ;",en:"IMPERIUM processes this data only on the Client’s documented instructions, ensures that authorised persons are bound by confidentiality and applies appropriate security measures;"},{fr:"le Client autorise le recours aux sous-traitants listés dans la [politique de confidentialité](/privacy#recipients) ; IMPERIUM l’informe de tout changement envisagé, auquel il peut s’opposer ;",en:"the Client authorises the sub-processors listed in the [privacy policy](/privacy#recipients); IMPERIUM informs the Client of any intended change, to which it may object;"},{fr:"IMPERIUM aide le Client à répondre aux demandes des personnes concernées et à respecter ses obligations de sécurité et d’analyse d’impact ;",en:"IMPERIUM helps the Client respond to data subject requests and meet its security and impact assessment obligations;"},{fr:"IMPERIUM notifie au Client toute violation de données dans les 48 heures après en avoir pris connaissance ;",en:"IMPERIUM notifies the Client of any personal data breach within 48 hours of becoming aware of it;"},{fr:"à la fin de l’Abonnement, IMPERIUM restitue les données au Client s’il le demande, puis les supprime, sauf obligation légale de conservation ;",en:"when the Subscription ends, IMPERIUM returns the data to the Client on request, then deletes it, unless the law requires it to be kept;"},{fr:"IMPERIUM met à disposition les informations nécessaires pour démontrer le respect de ces obligations et permet les audits raisonnables, à la charge du Client, avec un préavis de 30 jours.",en:"IMPERIUM makes available the information needed to demonstrate compliance with these obligations and allows reasonable audits, at the Client’s expense, with 30 days’ notice."}]}]},{id:"hosting",title:{fr:"Contenus hébergés et signalements",en:"Hosted content and notices"},blocks:[{kind:"p",text:{fr:`IMPERIUM héberge le Site du Client. Toute personne peut signaler un contenu illicite à ${s}, selon les modalités des [mentions légales](/legal-notice#report). IMPERIUM peut retirer ou rendre inaccessible un contenu manifestement illicite ; le Client en est alors informé, avec les motifs de la décision et les moyens de la contester (règlement (UE) 2022/2065, art. 16 et 17).`,en:`IMPERIUM hosts the Client’s Website. Anyone may report illegal content to ${s}, as set out in the [legal notice](/legal-notice#report). IMPERIUM may remove or disable access to manifestly illegal content; the Client is then informed, with the reasons for the decision and how to challenge it (Regulation (EU) 2022/2065, art. 16 and 17).`}}]},{id:"references",title:{fr:"Références",en:"References"},blocks:[{kind:"p",text:{fr:"IMPERIUM peut citer le nom du Client et présenter le Site parmi ses réalisations, sur son site et ses réseaux, sauf refus du Client exprimé par écrit, à tout moment.",en:"IMPERIUM may mention the Client’s name and show the Website among its work, on its website and social networks, unless the Client objects in writing, at any time."}}]},{id:"force",title:{fr:"Force majeure",en:"Force majeure"},blocks:[{kind:"p",text:{fr:"Aucune partie n’est responsable d’un manquement causé par un événement de force majeure au sens de l’article 1218 du Code civil. Les obligations concernées sont suspendues pendant sa durée ; si l’empêchement dure plus de 30 jours, chaque partie peut résilier l’Abonnement par email.",en:"Neither party is liable for a failure caused by force majeure within the meaning of article 1218 of the French Civil Code. The obligations concerned are suspended while it lasts; if it lasts more than 30 days, either party may terminate the Subscription by email."}}]},{id:"confidentiality",title:{fr:"Confidentialité",en:"Confidentiality"},blocks:[{kind:"p",text:{fr:"Chaque partie garde confidentielles les informations non publiques reçues de l’autre, pendant l’Abonnement et trois ans après sa fin, sauf obligation légale de les communiquer.",en:"Each party keeps confidential the non-public information received from the other, during the Subscription and for three years after it ends, unless the law requires disclosure."}}]},{id:"changes",title:{fr:"Modification des Conditions",en:"Changes to the Terms"},blocks:[{kind:"p",text:{fr:"IMPERIUM peut faire évoluer les Conditions. La nouvelle version s’applique aux commandes passées après sa publication. Pour un Abonnement en cours, elle est notifiée par email au moins 30 jours avant son entrée en vigueur ; le Client qui la refuse peut résilier avant cette date, faute de quoi elle s’applique.",en:"IMPERIUM may update the Terms. The new version applies to orders placed after it is published. For an ongoing Subscription, it is notified by email at least 30 days before it takes effect; a Client who refuses it may cancel before that date, failing which it applies."}}]},{id:"law",title:{fr:"Droit applicable et litiges",en:"Governing law and disputes"},blocks:[{kind:"p",text:{fr:"Les Conditions sont soumises au droit français. La version française fait foi.",en:"The Terms are governed by French law. The French version prevails; this translation is provided for information."}},{kind:"p",text:{fr:`En cas de difficulté, les parties recherchent d’abord une solution amiable : le Client écrit à ${s} et reçoit une réponse sous 15 jours. À défaut d’accord dans les 30 jours, le litige est porté devant les juridictions compétentes.`,en:`If a difficulty arises, the parties first seek an amicable solution: the Client writes to ${s} and receives an answer within 15 days. Failing agreement within 30 days, the dispute is brought before the competent courts.`}}]}]},Y=[w,I,C,S];export{M as a,y as b,S as c,x as d,Y as l,w as n,C as p,E as s,I as t};
